const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const fs = require('fs');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

let canvasState = [];

io.on('connection', (socket) => {
  console.log('A user connected');

  socket.emit('init', canvasState);

  socket.on('draw', (data) => {
    canvasState.push(data);
    socket.broadcast.emit('draw', data);
  });

  socket.on('clear', () => {
    canvasState = [];
    io.emit('clear');
  });
});

app.use(express.static('client/build'));

server.listen(3000, () => {
  console.log('Server listening on *:3000');
});

import React, { useRef, useEffect } from 'react';
import { io } from 'socket.io-client';

const socket = io();

function App() {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    socket.on('draw', drawLine);
    socket.on('clear', () => ctx.clearRect(0, 0, canvas.width, canvas.height));
    socket.on('init', (lines) => lines.forEach(drawLine));

    function drawLine({ x0, y0, x1, y1 }) {
      ctx.beginPath();
      ctx.moveTo(x0, y0);
      ctx.lineTo(x1, y1);
      ctx.stroke();
    }

    let drawing = false;

    const startDraw = (e) => {
      drawing = true;
      [lastX, lastY] = [e.nativeEvent.offsetX, e.nativeEvent.offsetY];
    };

    const endDraw = () => drawing = false;

    let lastX, lastY;

    const draw = (e) => {
      if (!drawing) return;
      const [x, y] = [e.nativeEvent.offsetX, e.nativeEvent.offsetY];
      socket.emit('draw', { x0: lastX, y0: lastY, x1: x, y1: y });
      drawLine({ x0: lastX, y0: lastY, x1: x, y1: y });
      [lastX, lastY] = [x, y];
    };

    canvas.addEventListener('mousedown', startDraw);
    canvas.addEventListener('mouseup', endDraw);
    canvas.addEventListener('mousemove', draw);

    return () => {
      socket.off('draw');
      socket.off('clear');
      socket.off('init');
    };
  }, []);

  return (
    <div>
      <canvas ref={canvasRef} width={800} height={600} style={{ border: '1px solid black' }} />
      <button onClick={() => socket.emit('clear')}>Clear</button>
    </div>
  );
}

export default App;
